part5_css_system.card_common_styles:
.gaugeItem {
    background: #FFFFFF;
    border-radius: 12px;
    padding: 20px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.08);
}

.gaugeItem .headText {
    font-size: 28px;
    font-weight: 700;
    color: #3B4458;
    margin-bottom: 16px;
    padding-bottom: 12px;
    border-bottom: 2px solid #E5E7EB;
}

.gaugeItem.ingWarning {
    background: #FFF5F5;
    border: 4px solid #F05E5E;
    animation: pulse 2s infinite;
}

part6_javascript_system.initialization_flow:
// 페이지 로드 시 실행 순서
document.addEventListener('DOMContentLoaded', function() {
    updateTime();
    setInterval(updateTime, 1000);

    // 카드 업데이트
    updateCard1(dashboardData.card1);
    updateCard2(dashboardData.card2);
    updateCard3(dashboardData.card3);
    updateCard5(dashboardData.card5);
    updateCard6(dashboardData.card6);
});

part7_data_structure.full_schema:
const dashboardData = {
    // 메타 정보
    "date": "20251124",  // YYYYMMDD 형식

    // 카드1: 입고현황
    "card1": {
        "totalCount": 57,           // number: 총 입고 건수
        "progressRate": 71.9,       // number: 진척률 (0~100)
        "inboundRiskyCount": 1,     // number: 유의상품 건수
        "riskyItems": [             // array: 유의상품 목록
            {
                "productName": "상품명",
                "inboundExpiry": "20251210",  // 입고분 소비기한
                "stockExpiry": "20251215"     // 기존 재고 소비기한
            }
        ]
    },

    // 카드2: 자사출고
    "card2": {
        "amount": 60609461,         // number: 출하금액 (원)
        "compare": -29.4,           // number: 전일대비 (%)
        "totalLabel": 5412,         // number: 총 라벨 건수
        "unprintedLabel": 0,        // number: 미발행 라벨
        "irregularTotal": 14,       // number: 비정형 총 건수
        "irregularUnprinted": 9     // number: 비정형 미출력
    },

    // 카드3: 지방출고
    "card3": {
        "amount": 28358148,         // number: 출하금액 (원)
        "compare": 130.4,           // number: 전일대비 (%)
        "unprintedPicking": 0,      // number: 미발행 피킹리스트
        "destinations": {           // object: 13개 배송처
            "jeju": 5,
            "jecheon": 3,
            "honam": 8,
            "gumi": 2,
            "gyeryong": 4,
            "eumseong": 12,
            "yongin2": 6,
            "yongin3": 3,
            "ansan": 15,
            "yangsan": 7,
            "yangsan2": 2,
            "hanex": 4,
            "kids": 2
        }
    },

    // 카드5: 피킹유의
    "card5": {
        "totalCount": 10,           // number: 총 유의상품 건수
        "urgentCount": 2,           // number: 긴급 (유효비 ≤10%)
        "warningCount": 8,          // number: 주의 (유효비 11~20%)
        "riskyItems": [             // array: 유의상품 목록
            {
                "location": "K040901",
                "productName": "상품명",
                "expiryDate": "20251205",   // 또는 "2025-12-05"
                "validityRatio": 8.0        // 유효유통비 (%)
            }
        ]
    },

    // 카드6: 재고현황 (5개 섹션)
    "card6": {
        // 섹션1: 총재고 + 적치율
        "inventory": {
            "total_value": 17680000  // number: SUM(가용수량 × 단가)
        },
        "storageRate": {
            "rate": 45.2             // number: (재고있는 상단로케이션/524) × 100
        },

        // 섹션2: 선입선출 위반
        "fifo": [                    // array: 위반 목록 (0건이면 빈 배열)
            {
                "lower": {           // 하단 (출고용) - 소비기한 더 늦음
                    "product": "닭가슴살채",
                    "location": "A010101",
                    "expiry": "25.12.05"
                },
                "upper": {           // 상단 (보관용) - 소비기한 더 빠름
                    "location": "B020101",
                    "expiry": "25.12.03"
                }
            }
        ],

        // 섹션3: 미출/부분출고
        "partial": [                 // array: 미출/부분출고 목록
            {
                "delivery_group": "4331",
                "delivery_name": "용인2",
                "product_name": "(캘리)참깨소스(2kg)",
                "unit": "EA(2kg)",
                "original_qty": 4,   // 원주문 수량
                "order_qty": 2       // 현재 오더 수량 (0이면 미출)
            }
        ],

        // 섹션4: 삭제현황
        "deleteAnsan": [             // array: 안산 삭제 목록
            {
                "product_name": "상품명",
                "unit": "EA",
                "qty": 5
            }
        ],
        "deleteEumseong": [          // array: 음성 삭제 목록
            {
                "product_name": "상품명",
                "unit": "BOX",
                "qty": 3
            }
        ],

        // 섹션5: 미할당 입고
        "unallocated": [             // array: 미할당 입고 목록
            {
                "product_name": "상품명",
                "unit": "EA",
                "qty": 10,
                "center": "안산"     // 9개 센터 중 하나
            }
        ]
    }
};

step.example_code:
@app.route('/api/dashboard')
def get_dashboard():
    data = load_dashboard_data()  # CSV 읽어서 계산
    return jsonify(data)

async function fetchDashboardData() {
    try {
        const response = await fetch('/api/dashboard');
        const data = await response.json();

        updateCard1(data.card1);
        updateCard2(data.card2);
        updateCard3(data.card3);
        updateCard5(data.card5);
        updateCard6(data.card6);

        updateLastRefreshTime();
    } catch (error) {
        console.error('데이터 로드 실패:', error);
    }
}

// 페이지 로드 시 + 30초마다
fetchDashboardData();
setInterval(fetchDashboardData, 30000);
